    const database = await makeDatabasePath();
    const first = await invoke(
      database,
      "add",
      "--title",
      "  First task  ",
      "--tags",
      "Work, urgent,WORK",
      "--due",
      "2024-02-29",
    );
    expect(first.exitCode).toBe(0);
